'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var deepEqual = require( '@stdlib/assert/deep-equal' );
var format = require( '@stdlib/string/format' );
var get = require( '@stdlib/utils/json-pointer/get' );


// MAIN //

/**
* Tests whether a value at a JSON Pointer path deeply equals a given value.
*
* ## Notes
*
* -   Implements the `test` operation per RFC 6902 §4.6.
* -   Uses deep structural equality comparison via `@stdlib/assert/deep-equal`.
* -   Returns a boolean — does not throw on test failure.
* -   The path must exist (will throw if it does not).
*
* @param {(Object|Array)} document - source JSON document
* @param {string} path - JSON Pointer string
* @param {*} value - expected value
* @throws {TypeError} first argument must be an object or array
* @throws {TypeError} second argument must be a string
* @throws {Error} path must reference an existing location
* @returns {boolean} boolean indicating whether the value at the path equals the expected value
*
* @example
* var doc = { 'foo': 'bar' };
* var bool = testOp( doc, '/foo', 'bar' );
* // returns true
*
* @example
* var doc = { 'foo': [ 1, 2, 3 ] };
* var bool = testOp( doc, '/foo', [ 1, 2, 3 ] );
* // returns true
*
* @example
* var doc = { 'foo': 'bar' };
* var bool = testOp( doc, '/foo', 'baz' );
* // returns false
*/
function testOp( document, path, value ) {
	var current;

	if ( !isPlainObject( document ) && !isArray( document ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an object or an array. Value: `%s`.', document ) );
	}
	if ( !isString( path ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a string. Value: `%s`.', path ) );
	}

	current = get( document, path );

	// Deep structural comparison:
	return deepEqual( current, value );
}


// EXPORTS //

module.exports = testOp;
